#!/usr/bin/env bash
set +e
ADM="$(docker exec nyv-gateway printenv DATABASE_URL_ADMIN 2>/dev/null)"
ADM="${ADM%\"}"; ADM="${ADM#\"}"
ADM="$(echo "$ADM" | sed -E 's/sslmode=no-verify/sslmode=require/; s/sslmode=verify-full/sslmode=require/; s/sslmode=verify-ca/sslmode=require/')"
if [ -z "$ADM" ]; then echo "FATAL: DATABASE_URL_ADMIN not set"; exit 1; fi
SQL="$(echo '' | base64 -d)"
echo "SQL_BYTES=${#SQL}"
docker run --rm --network host -e PGURL="$ADM" -e SQL="$SQL" postgres:16-alpine   sh -c 'psql "$PGURL" -v ON_ERROR_STOP=1 -c "$SQL"' 2>&1 | tail -8
echo "=== per-jurisdiction counts (after) ==="
docker run --rm --network host -e PGURL="$ADM" postgres:16-alpine   sh -c 'psql "$PGURL" -At -F "|" -c "SELECT jurisdiction, count(*) FROM nv_statutes GROUP BY jurisdiction ORDER BY jurisdiction; SELECT '"'"'TOTAL'"'"', count(*) FROM nv_statutes;"' 2>&1
